const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const wilmington = ee.Geometry.Point([-77.9447, 34.2257]).buffer(5000); // 5km buffer around Wilmington, NC
  const startDate = '2018-01-01';
  const endDate = '2018-12-31';

  // 2. Data Acquisition & Check
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(wilmington);

  const collectionSize = chirps.size().getInfo();
  console.log(`2018 CHIRPS Images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum annual precipitation
  const annualPrecip = chirps.sum();

  // Check valid pixels
  const pixelCount = annualPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: wilmington,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean precipitation in mm
  const precipMm = annualPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: wilmington,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // 5. Validation & Final Answer
  console.log(`Annual precipitation: ${precipMm?.toFixed(1)} mm`);

  if (precipMm === null || precipMm === undefined || isNaN(precipMm)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Convert mm to inches (1 inch = 25.4 mm)
  const precipInches = precipMm / 25.4;
  console.log(`Annual precipitation: ${precipInches?.toFixed(1)} inches`);

  // Validate reasonable range (0-200 inches = 0-5080 mm)
  if (precipMm < 0 || precipMm > 5080) {
    console.log("<answer>C3</answer>");
    return;
  }

  if (precipInches >= 90) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
